"""M2 kit data and offline source records. Mechanics are explicit mod adaptations.
See docs/FOUNDATION_KIT_DESIGNS.md before changing this catalogue.
"""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1];DATA=ROOT/'src/main/resources/data/mha/mha'
def write(path,obj):path.parent.mkdir(parents=True,exist_ok=True);path.write_text(json.dumps(obj,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
def move(id,name,slot,shape,timing,cost,cooldown,range,damage,mastery,trial,description):
    return dict(id=id,name=name,slot=slot,shape=shape,startup=timing[0],active=timing[1],recovery=timing[2],stamina=cost[0],strain=cost[1],cooldown=cooldown,range=range,damage=damage,mastery=mastery,trial=trial,description=description+' Mod-original timing/balance and working move label.')
def main():
    explosion=['palm_burst','blast_dash','ap_shot','recoil_dodge','stun_grenade','burst_volley','aerial_redirection','howitzer_impact']
    old=json.loads((DATA/'moves.json').read_text());rows=[m for m in old if m['id'] in explosion];assert len(rows)==8
    thermal=[
      move('ice_shot','Ice Shot','TECHNIQUE','RAY',(6,1,9),(12,15),30,12,5,0,'','Right-side precision ice. Lowers temperature by 15; solid cover stops the ray.'),
      move('flame_jet','Flame Jet','TECHNIQUE','CONE',(4,1,10),(14,15),35,5,4,0,'','Left-side short flame cone. Raises temperature by 15; does not ignite terrain.'),
      move('ice_wall','Ice Wall','TECHNIQUE','WALL',(10,1,16),(24,25),140,6,0,5,'field_control','A three-by-three temporary ice wall. Empty, unoccupied positions only; finite lifetime and no block drops.'),
      move('ice_ramp','Ice Ramp','UTILITY','RAMP',(5,1,12),(18,10),90,5,0,0,'','A temporary stepped rescue route. Collision and protection rules apply; never places inside entities.'),
      move('flame_sweep','Flame Sweep','TECHNIQUE','CONE',(10,1,16),(25,25),90,7,6,12,'field_movement','A wider flame pressure sweep. Raises temperature by 25; cover and recovery provide counterplay.'),
      move('flashfreeze','Flashfreeze','TECHNIQUE','SPHERE',(14,1,18),(28,30),150,5,3,20,'field_rescue','A bounded cold pulse with a short slow. Bosses resist control; no immobilising terrain is placed on targets.'),
      move('thermal_shock','Thermal Shock','TECHNIQUE','RAY',(14,1,20),(34,0),160,12,9,35,'field_defence','Mix both sides in a precision burst. Requires temperature within 25 of balance, then returns it to zero.'),
      move('flashfreeze_heatwave','Flashfreeze Heatwave','CAPSTONE','SPHERE',(30,1,35),(55,0),600,8,13,50,'field_capstone','A long, interruptible mixed release. Requires temperature within 40 of balance; no terrain destruction.')]
    hardening=[
      move('harden','Harden','TECHNIQUE','GUARD',(3,40,8),(10,8),100,0,0,0,'','A two-second hardening window reduces damage by 35%. Impacts add fatigue; ordinary weapons remain usable.'),
      move('braced_step','Braced Step','UTILITY','STEP',(2,1,8),(14,6),50,2,0,0,'','Short grounded footwork. This is complementary movement, without teleportation or invulnerability.'),
      move('hardened_strike','Hardened Strike','TECHNIQUE','CONE',(5,1,10),(14,8),30,3.5,6,5,'field_control','A short hardened melee blow. A legitimately primed counter adds one bounded follow-up bonus.'),
      move('counter_guard','Counter Guard','TECHNIQUE','GUARD',(2,20,10),(18,12),100,0,0,12,'field_movement','A short guard window. Blocking a real hostile impact primes one strike; no recursive reflected damage.'),
      move('stone_anchor','Stone Anchor','TECHNIQUE','GUARD',(5,60,15),(25,20),180,0,0,20,'field_rescue','Rooted hardening adds knockback resistance while holding position. It reduces damage, without immunity.'),
      move('breakline','Breakline','TECHNIQUE','CONE',(10,1,18),(28,22),100,4,7,35,'field_defence','A close line-breaking blow with bounded knockback. Walls, team policy and armour still apply.'),
      move('bodyguard_advance','Bodyguard Advance','UTILITY','STEP',(4,1,14),(25,18),120,3,0,35,'field_movement','A short braced advance with a brief hardening window. Protection requires physically taking position.'),
      move('unbreakable','Unbreakable','CAPSTONE','GUARD',(20,100,25),(45,35),600,0,0,50,'field_capstone','Five seconds of 50% reduction, with fatigue and punishable recovery. No invulnerability or flight.')]
    electric=[
      move('spark_touch','Spark Touch','TECHNIQUE','CONE',(4,1,8),(10,8),28,3,4,0,'','A close electrical strike. Spends charge and adds overload; ally and PvP protections remain active.'),
      move('grounding_step','Grounding Step','UTILITY','STEP',(2,1,8),(12,4),50,2,0,0,'','Ordinary grounded footwork and a small load reduction. Not electric teleportation.'),
      move('directional_arc','Directional Arc','TECHNIQUE','RAY',(8,1,12),(18,16),65,12,6,5,'field_control','A narrow aimed discharge that stops at solid cover and the first eligible target.'),
      move('static_net','Static Net','TECHNIQUE','SPHERE',(12,1,16),(24,20),130,4,2,12,'field_movement','A short nearby disruption pulse. Brief slows, boss resistance and protection checks prevent stun-lock.'),
      move('charge_capacitor','Charge Capacitor','TECHNIQUE','CHARGE',(10,40,12),(25,0),180,0,0,20,'field_rescue','An exposed recharge stance. Adds 30 charge and 10 load; it grants no mastery for repeated use.'),
      move('chain_discharge','Chain Discharge','TECHNIQUE','CHAIN',(14,1,18),(30,28),130,10,5,35,'field_defence','Up to three eligible targets. Each hop needs six-block range and clear sight; never recursively chains/reflections.'),
      move('grounding_stance','Grounding Stance','UTILITY','GROUND',(5,40,12),(16,0),150,0,0,35,'field_movement','A grounded recovery stance that removes 25 overload. It provides no damage immunity.'),
      move('maximum_discharge','Maximum Discharge','CAPSTONE','SPHERE',(28,1,32),(50,60),600,7,12,50,'field_capstone','A heavy radial discharge adds 70 load. Exceeding tolerance causes a visible six-second recovery; ordinary survival remains usable.')]
    kit_rows=[('explosion','Explosion','Pressure / precision and recoil','Blast strain',0xffff974f,explosion,['palm_burst','blast_dash']),('half_cold_half_hot','Half-Cold Half-Hot','Area control / rescue routes','Temperature',0xff69c9f5,[m['id'] for m in thermal],['ice_shot','flame_jet','ice_ramp']),('hardening','Hardening','Close protection / counterattacks','Fatigue',0xffdc6a5e,[m['id'] for m in hardening],['harden','braced_step']),('electrification','Electrification','Disruption / aimed discharge','Charge / overload',0xffffdf69,[m['id'] for m in electric],['spark_touch','grounding_step'])]
    write(DATA/'kits.json',[dict(zip(['id','name','role','resource','color','moves','starters'],r),color=r[4]-4294967296 if r[4]>2147483647 else r[4]) for r in kit_rows]);write(DATA/'moves.json',rows+thermal+hardening+electric)
    meta=[('half_cold_half_hot','Half-Cold Half-Hot','半冷半燃','Shoto Todoroki / 轟焦凍','01-05','The official profile describes right-side ice and left-side heat/flame.','Signed temperature and stamina; alternate sides to maintain control.','Overusing one side reaches a thermal extreme. Underwater fire is refused.',['Solid cover and flanking.','Bait repeated use of one side; punish windup/recovery.'],['Finite collision-safe ice cover and temporary stepped rescue routes.']),('hardening','Hardening','硬化','Eijiro Kirishima / 切島鋭児郎','01-08','The official profile describes whole-body hardening useful for offence and defence.','Stamina and hardening fatigue; real guarded impacts increase fatigue.','No invulnerability. Range, fatigue and recovery remain meaningful.',['Keep range or use cover.','Pressure fatigue; avoid predictable short counters.'],['Physical bodyguard positioning and protected rescue work.']),('electrification','Electrification','帯電','Denki Kaminari / 上鳴電気','01-11','The official profile describes bodily discharge and a temporary overload drawback above the user\'s tolerance.','Stamina, charge and overload. Charge recovers; grounding lowers load.','Underwater electrical casting is refused. Excess load creates a finite recovery period.',['Separate targets and break line of sight.','Bait heavy output and punish the recharge/recovery window.'],['Controlled short disruption and supervised support exercises.'])]
    for id,name,japanese,user,page,lore,resource,drawback,counters,utility in meta:
        kit=next(k for k in kit_rows if k[0]==id)
        obj=dict(id=id,name=name,localizedNames=[japanese+' (official Japanese label)',name+' (working English label)'],knownUsers=[user+' — original user; later story details omitted'],sourceMedium='Main-series anime; manga references not yet separately verified',sourceWork='My Hero Academia',continuity='Main-series quirk. No additional continuity claim is inferred from source medium.',firstCharacterAppearance='Not yet verified against primary episode material.',firstDemonstration='No verified TV season/episode is published for this entry yet.',firstNamedExplanation='Japanese label verified on the official character profile; first TV explanation not yet verified.',lore=lore,adaptation='The eight-action kit, resources, training requirements and numerical balance are mod adaptations. Ordinary footwork/support actions are complementary training, not new canonical powers.',role=kit[2],resource=resource,drawback=drawback,counters=counters,nonCombatUtility=utility,equipment='The Cadet suit is ordinary equipment. It never assigns this quirk or grants a move. New support equipment is distinguished from the actual power.',acquisition='Experimental development kit. Permission-checked creative assignment restores earned mastery. Field objectives and meaningful per-quirk mission practice unlock techniques; general rewards are single-claim. Server-enabled starting/reroll pools are authoritative.',verification='Original user, Japanese label and the stated basic principle checked on the official profile on 28 October 2026. English labels are working labels; no unverified first-appearance claim is made.',references=[dict(title='Official character profile',url='https://www.heroaca.com/character/chara_group01/'+page+'/',supports='Original user, Japanese quirk label and basic principle only.',season=1,warning='The live official page contains later-series spoilers. This offline entry omits those details.')])
        write(DATA/'quirks'/f'{id}.json',obj)
    print('Prepared four experimental kit definitions and 32 move records, with three source-labelled offline guide entries. Runtime implementation and acceptance remain separate.')
    from make_extra_kits import main as extra_kits
    extra_kits()
if __name__=='__main__':main()
